namespace Acta;

/// <summary>
/// Service-owned execution boundary. One deployable service owns one <see cref="NamespaceEntity"/>; replicas
/// of that service share it. A deploy writes the row, and a worker start reads it.
/// </summary>
[DbTable("namespaces")]
[DbPrimaryKey(Name = "pk_namespaces", Columns = ["namespace_id"])]
[DbUniqueIndex(Name = "ux_namespaces_name", Columns = ["namespace_name"], Usage = "uniqueness")]
internal sealed class NamespaceEntity : IEntity<int>
{
    /// <summary>
    /// DB-assigned identity (<c>IDENTITY(1,1)</c> on SQL Server, <c>GENERATED BY DEFAULT AS IDENTITY</c>
    /// on Postgres). Referenced by every hot table via <c>namespace_id</c>. Callers never pick the
    /// value; a deploy inserts the row by <see cref="NamespaceName"/> (<c>StartDeployment</c>), and a worker
    /// start reads the assigned id back (<c>StartWorker</c>).
    /// </summary>
    [DbColumn("namespace_id", DbKind.Int32)]
    public int Id { get; init; }

    /// <summary>
    /// Operator-readable namespace name. Unique. Kebab-case.
    /// </summary>
    [DbColumn("namespace_name", DbKind.AsciiString, Size = 128)]
    public string NamespaceName { get; init; } = default!;

    /// <summary>
    /// Owning team identifier surfaced on operator dashboards. Unicode-capable.
    /// </summary>
    [DbColumn("owner_team", DbKind.UnicodeString, Size = TextLimits.NamespaceOwnerTeam)]
    public string? OwnerTeam { get; internal set; }

    /// <summary>
    /// Operator-readable description of what this namespace owns. Unicode-capable.
    /// </summary>
    [DbColumn("description", DbKind.UnicodeString, Size = TextLimits.NamespaceDescription)]
    public string? Description { get; internal set; }

    /// <summary>
    /// Namespace lifecycle status. Supplied at INSERT by the StartWorker registration (no server-side
    /// default), mirroring the tenant convention. Enforced at enqueue: EnqueueJob/EnqueueJobs reject
    /// with a distinguishable error when the resolved namespace is not Active.
    /// </summary>
    [DbColumn("namespace_status_code")]
    public NamespaceStatusCode Status { get; internal set; }

    /// <summary>
    /// The version of the app whose deploy last landed in the namespace, a row of <c>deployments</c>. NULL while no
    /// deploy has, which leaves a namespace that only a worker start has written.
    /// </summary>
    [DbColumn("deployment_version", DbKind.AsciiString, Size = 128, CaseExact = true)]
    public string? DeploymentVersion { get; internal set; }

    /// <summary>When the namespace row was first created. Set server-side.</summary>
    [DbColumn("created_at_utc", DbKind.UtcInstant, Default = DbDefault.UtcNow)]
    public DateTime CreatedAtUtc { get; set; }

    /// <summary>When the namespace row was last updated. Set server-side on every mutation.</summary>
    [DbColumn("modified_at_utc", DbKind.UtcInstant, Default = DbDefault.UtcNow)]
    public DateTime ModifiedAtUtc { get; set; }

    /// <summary>
    /// Optimistic-concurrency token; SPs manually increment on UPDATE.
    /// </summary>
    [DbColumn("version", DbKind.Int32, Default = DbDefault.Zero)]
    [DbConcurrencyToken]
    public int Version { get; set; }

    /// <summary>
    /// When the namespace's next recovery pass is due; NULL means due now. A worker runs the pass only when its update
    /// moves this one interval on, so one pass runs per namespace per interval, and a worker that dies mid-pass holds
    /// nothing. Not an operator setting, so it moves neither <see cref="Version"/> nor <see cref="ModifiedAtUtc"/>.
    /// </summary>
    [DbColumn("recovery_due_at_utc", DbKind.UtcInstant)]
    public DateTime? RecoveryDueAtUtc { get; set; }
}
